/**
 * Where a deploy resolves to, computed once from the deploy-target verdict. The
 * dry-run report and its JSON both read this, so the human and machine outputs
 * can't drift.
 */
export interface DeployTarget {
  /** Whether the deploy creates a new application/studio or updates an existing one. */
  action: 'create' | 'update'
  /** `null` until the deploy creates the application. */
  id: string | null
  title: string | null
  type: 'coreApp' | 'studio'
  url: string | null

  /** Absent on a plain app, whose backend reports `appHost` instead. */
  slug?: string
}

export interface DeployCheck extends Check {
  /** The backend's record, verbatim; `--json` reports it once the deploy succeeds. */
  application?: object
  /** Set on the deploy-target check with the resolved target both reporters read. */
  target?: DeployTarget
}

export type DeployCheckReporter = CheckReporter<DeployCheck>

export async function checkPackageVersion(
  reporter: DeployCheckReporter,
  {moduleName, workDir}: {moduleName: string; workDir: string},
): Promise<string | null> {
  const version = await getLocalPackageVersion(moduleName, workDir)
  reporter.report(
    version
      ? {message: `Using ${moduleName} ${version}`, status: 'pass'}
      : {
          message: `Failed to find installed ${moduleName} version`,
          solution: `Install ${moduleName} in this project`,
          status: 'fail',
        },
  )
  return version
}

export function checkAutoUpdates(
  reporter: DeployCheckReporter,
  {cliConfig, flags}: {cliConfig: CliConfig; flags: DeployFlags},
): boolean {
  const {enabled, issue} = resolveAutoUpdates({cliConfig, flags})

  if (issue) {
    reporter.report({
      message: getAutoUpdateIssueMessage(issue),
      // A config conflict makes a real deploy refuse to run; deprecations only warn
      status: issue.type === 'conflicting-config' ? 'fail' : 'warn',
    })

    // The deprecated top-level config also gets the styled migration edit, the
    // same second warning the build/dev path prints through shouldAutoUpdate.
    if (issue.type === 'deprecated-config') {
      reporter.report({
        message: getAutoUpdateMigrationHint(cliConfig.autoUpdates),
        status: 'warn',
      })
    }
  }

  return enabled
}

/**
 * The dry-run form of the `app.id` config check a real deploy runs in
 * `findUserApplication`: a conflict fails (both `app.id` and `deployment.appId`
 * set), the deprecated config alone warns.
 */
export function checkAppId(
  reporter: DeployCheckReporter,
  {cliConfig}: {cliConfig: CliConfig},
): void {
  const issue = resolveAppIdIssue(cliConfig)
  if (issue === 'conflicting-config') {
    reporter.report({
      message: 'Both `app.id` (deprecated) and `deployment.appId` are set',
      solution: 'Remove `app.id` from sanity.cli.ts',
      status: 'fail',
    })
  } else if (issue === 'deprecated-config') {
    reporter.report({
      message: 'The `app.id` config is deprecated',
      solution: 'Move it to `deployment.appId` in sanity.cli.ts',
      status: 'warn',
    })
  }
}

/**
 * The origin a federated studio deployed with --external is registered
 * at. Only a first deploy registers one; a redeploy keeps the URL it has.
 */
export function checkExternalUrl(
  reporter: DeployCheckReporter,
  {appId, url}: {appId: string | undefined; url: string | undefined},
): string | undefined {
  if (appId) return undefined

  if (!url) {
    reporter.report({
      exitCode: exitCodes.USAGE_ERROR,
      message: 'A first external deploy needs the URL your host serves the build from',
      solution: 'Pass it with --url, for example --url https://studio.example.com',
      status: 'fail',
    })
    return undefined
  }

  const normalized = normalizeUrl(url)
  const validation = validateUrl(normalized)
  if (validation !== true) {
    reporter.report({
      exitCode: exitCodes.USAGE_ERROR,
      message: validation,
      solution:
        'Pass --url with an http or https URL, for example --url https://studio.example.com',
      status: 'fail',
    })
    return undefined
  }

  // The Dashboard loads the remote from the origin root, so a path would never be fetched.
  const {hash, origin, pathname, search} = new URL(normalized)
  if (pathname !== '/' || search || hash) {
    reporter.report({
      exitCode: exitCodes.USAGE_ERROR,
      message: '--url must be an origin with no path, query or hash',
      solution:
        'Pass the origin your host serves the build from, for example --url https://studio.example.com',
      status: 'fail',
    })
    return undefined
  }

  reporter.report({message: `Registers at ${origin}`, status: 'pass'})
  return origin
}

export async function checkBuild<T>(
  reporter: DeployCheckReporter,
  {
    build,
    skipReason,
    successMessage,
  }: {build: () => Promise<T>; skipReason: string | undefined; successMessage: string},
): Promise<T | undefined> {
  if (skipReason) {
    reporter.report({message: skipReason, status: 'skip'})
    return undefined
  }

  const result = await runStep(reporter, {
    debug: deployDebug,
    formatError: (err) => `Build failed: ${getErrorMessage(err)}`,
    name: 'build',
    solution: 'Fix the build error above, then retry',
    work: async () => {
      const result = await build()
      reporter.report({message: successMessage, status: 'pass'})
      return result
    },
  })
  return result ?? undefined
}

/**
 * The deploy directory must exist and hold the right build output: a federation
 * remote for a workbench app, an `index.html` SPA otherwise.
 */
export async function verifyOutputDir({
  isWorkbenchApp,
  reporter,
  sourceDir,
}: {
  isWorkbenchApp: boolean
  reporter: DeployCheckReporter
  sourceDir: string
}): Promise<Record<string, unknown> | undefined> {
  const spin = spinner('Verifying local content...').start()
  let mfManifest: Record<string, unknown> | undefined
  try {
    if (isWorkbenchApp) mfManifest = await readBuiltManifest(sourceDir)
    else await checkDir(sourceDir)
    spin.succeed()
  } catch (err) {
    spin.fail()
    deployDebug('Error checking directory', err)
    reporter.report({
      message: getErrorMessage(err),
      solution: 'Run the build first, or check the output directory',
      status: 'fail',
    })
  }
  return mfManifest
}

/**
 * The single diagnosis for each app deploy-target verdict, shared by the
 * dry-run report and the real deploy's unattended error paths so message,
 * fix, and exit code can't drift between the two.
 */
export function describeAppTarget(
  resolution: AppDeployTargetResolution,
  {title}: {title?: string} = {},
): DeployCheck {
  switch (resolution.type) {
    case 'blocked': {
      return {message: `Deploy target not resolved — ${resolution.message}`, status: 'skip'}
    }
    case 'found': {
      const {application} = resolution
      const title = application.title ?? application.appHost
      const url = application.url ?? getCoreAppUrl(application.organizationId, application.id)
      return {
        application,
        message: `Deploys to existing application "${title}" at ${url}`,
        status: 'pass',
        target: {
          action: 'update',
          id: application.id,
          title: application.title,
          type: 'coreApp',
          url,
        },
      }
    }
    case 'invalid': {
      return {
        message: APP_ID_NOT_FOUND_IN_ORGANIZATION,
        solution: 'Check `deployment.appId` matches an app in your organization',
        status: 'fail',
      }
    }
    case 'needs-input': {
      return {
        exitCode: exitCodes.USAGE_ERROR,
        message: `No \`deployment.appId\` configured (${resolution.existing.length} existing ${resolution.existing.length === 1 ? 'application' : 'applications'} to choose from)`,
        solution:
          'Set `deployment.appId` in sanity.cli.ts to deploy to an existing app, or run `sanity deploy --create --title "<name>" --yes` to create a new one',
        status: 'fail',
      }
    }
    case 'slug-taken': {
      return describeSlugTaken(resolution)
    }
    // Without --title, creating an app needs a prompt no unattended run can answer
    case 'would-create': {
      const {appHost} = resolution
      if (title) {
        return {
          message: `Would create a new application "${title}"${appHost ? ` with slug "${appHost}"` : ''}`,
          status: 'pass',
          target: {
            action: 'create',
            id: null,
            ...(appHost ? {slug: appHost} : {}),
            title,
            type: 'coreApp',
            url: null,
          },
        }
      }
      return {
        exitCode: exitCodes.USAGE_ERROR,
        message: 'No application to deploy to — creating one needs a title',
        solution:
          'Pass `--title "<name>"` or set `app.title` in sanity.cli.ts to create one, or set `deployment.appId` to deploy to an existing app',
        status: 'fail',
      }
    }
  }
}

/** One diagnosis for both the app and studio verdicts: they share a slug namespace. */
function describeSlugTaken({
  appHost,
  existing,
}: {
  appHost: string
  existing: DeployTargetApp
}): DeployCheck {
  return {
    application: existing,
    exitCode: exitCodes.USAGE_ERROR,
    message: `An application already exists at slug "${appHost}" in this organization (app ID ${existing.id})`,
    solution: `Add \`deployment: {appId: '${existing.id}'}\` to sanity.cli.ts to redeploy it`,
    status: 'fail',
    target: {
      action: 'update',
      id: existing.id,
      title: existing.title,
      type: existing.type,
      url: existing.url ?? null,
    },
  }
}

export function describeAppTargetError(err: unknown, organizationId: string | undefined): string {
  return (err as {statusCode?: number})?.statusCode === 403
    ? `You don’t have permission to view applications for the configured organization ID ("${organizationId}"). Verify the organization ID, or ask your organization’s admin for access.`
    : `Failed to resolve deploy target: ${getErrorMessage(err)}`
}

/**
 * Reports the app deploy target as a check and returns the resolved target;
 * `isWorkbenchApp` selects the backend. Both modes run it — a real deploy uses
 * it to reject a bad `appId` before building.
 */
export async function checkAppTarget(
  reporter: DeployCheckReporter,
  options:
    | {
        appId: string | undefined
        create?: boolean
        isWorkbenchApp?: false
        organizationId: string | undefined
        title?: string
      }
    | {
        appId: string | undefined
        hasAppView: boolean
        isWorkbenchApp: true
        organizationId?: string
        slug?: string
        title?: string
      },
): Promise<DeployCheck | null> {
  const {title} = options
  if (options.isWorkbenchApp) {
    const {appId, hasAppView, organizationId, slug} = options
    return runStep(reporter, {
      debug: deployDebug,
      name: 'target',
      work: async () => {
        const resolution = await resolveWorkbenchApp({appId, hasAppView, organizationId, slug})
        const check = describeAppTarget(resolution, {title})
        reporter.report(check)
        return check
      },
    })
  }

  const {appId, create, organizationId} = options
  return runStep(reporter, {
    debug: deployDebug,
    formatError: (err) => describeAppTargetError(err, organizationId),
    name: 'target',
    work: async () => {
      const check = describeAppTarget(
        await resolveAppDeployTarget({appId, create, organizationId}),
        {
          title,
        },
      )
      reporter.report(check)
      return check
    },
  })
}

/** Same contract as {@link describeAppTarget}, for the studio verdicts. */
export function describeStudioTarget(
  resolution: StudioDeployTargetResolution,
  {isExternal, isWorkbench, title}: {isExternal: boolean; isWorkbench?: boolean; title?: string},
): DeployCheck {
  const studioUrl = (host: string) => (isExternal ? host : `https://${host}.sanity.studio`)

  switch (resolution.type) {
    case 'blocked': {
      return {message: `Deploy target not resolved — ${resolution.message}`, status: 'skip'}
    }
    case 'found': {
      const {appHost} = resolution.application
      const url = resolution.application.url ?? (appHost ? studioUrl(appHost) : null)
      return {
        application: resolution.application,
        message: `Deploys to existing studio ${url}`,
        status: 'pass',
        target: {
          action: 'update',
          id: resolution.application.id,
          title: resolution.application.title,
          type: 'studio',
          url,
        },
      }
    }
    case 'invalid': {
      return {
        // A bad host is a usage error; other invalid targets exit 1
        exitCode: resolution.reason === 'invalid-host' ? exitCodes.USAGE_ERROR : 1,
        message: resolution.message,
        solution: 'Check `studioHost` and `deployment.appId` in sanity.cli.ts',
        status: 'fail',
      }
    }
    case 'needs-input': {
      return {
        exitCode: exitCodes.USAGE_ERROR,
        message: isExternal ? 'No external studio URL configured' : 'No studio hostname configured',
        solution: isExternal
          ? 'Set `studioHost` in sanity.cli.ts, or pass the full URL with --url'
          : 'Set `studioHost` in sanity.cli.ts, or pass a hostname with --url',
        status: 'fail',
      }
    }
    case 'slug-taken': {
      return describeSlugTaken(resolution)
    }
    case 'would-create': {
      const appHost = resolution.appHost
      const url = isWorkbench ? null : studioUrl(appHost)
      const result = {
        status: 'pass',
        target: {action: 'create', id: null, title: title || null, type: 'studio', url},
      } as const
      const titled = title ? ` titled "${title}"` : ''

      if (isExternal) {
        return {
          message: `Would register external studio at ${appHost}${titled}`,
          ...result,
        }
      }

      if (isWorkbench) {
        return {
          message: `Would create a new studio${title ? ` "${title}"` : ''} with slug "${appHost}" (name availability is checked on deploy)`,
          ...result,
          target: {...result.target, slug: appHost},
        }
      }

      return {
        message: `Would create studio hostname ${url}${titled} (name availability is checked on deploy)`,
        ...result,
      }
    }
  }
}

/**
 * Reports the studio deploy target as a check and returns the resolved target;
 * `isWorkbenchApp` selects the backend. Both modes run it — a real deploy uses
 * it to reject a bad `appId` before building.
 */
export async function checkStudioTarget(
  reporter: DeployCheckReporter,
  options:
    | {
        appId: string | undefined
        isExternal: boolean
        isWorkbenchApp?: false
        projectId: string | undefined
        studioHost: string | undefined
        title: string | undefined
        urlFlag: string | undefined
      }
    | {
        appId: string | undefined
        isWorkbenchApp: true
        organizationId?: string
        slug: string
        title?: string
      },
): Promise<DeployCheck | null> {
  const {title} = options
  const resolve = options.isWorkbenchApp
    ? resolveWorkbenchStudio(options)
    : resolveStudioDeployTarget(options)
  // A workbench studio's target is its slug, even when its build is hosted externally.
  const isExternal = options.isWorkbenchApp ? false : options.isExternal

  return runStep(reporter, {
    debug: deployDebug,
    formatError: (err) => `Failed to resolve deploy target: ${getErrorMessage(err)}`,
    name: 'target',
    work: async () => {
      const check = describeStudioTarget(await resolve, {
        isExternal,
        isWorkbench: !!options.isWorkbenchApp,
        title,
      })
      reporter.report(check)
      return check
    },
  })
}
